source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    candidates = []
    for axis, length, width in ((0, h, w), (1, w, h)):
        lines = []
        for i in range(length):
            vals = [grid[i][j] for j in range(width)] if axis == 0 else [grid[j][i] for j in range(width)]
            if len(set(vals)) == 1 and vals[0] != background:
                lines.append(i)
        if lines:
            candidates.append((axis, lines))

    if not candidates:
        return out
    axis, separators = max(candidates, key=lambda item: len(item[1]))
    length = h if axis == 0 else w
    width = w if axis == 0 else h
    segments = []
    start = 0
    for s in separators:
        if start < s:
            segments.append((start, s))
        start = s + 1
    if start < length:
        segments.append((start, length))
    if len(segments) < 2:
        return out

    # Repeat the non-background pattern at matching positions in each tile.
    groups = {}
    for a, b in segments:
        groups.setdefault(b - a, []).append((a, b))
    tile_groups = max(groups.values(), key=len)
    if len(tile_groups) < 2:
        return out
    for offset in range(tile_groups[0][1] - tile_groups[0][0]):
        for j in range(width):
            vals = []
            for a, b in tile_groups:
                i = a + offset
                vals.append(grid[i][j] if axis == 0 else grid[j][i])
            features = {v for v in vals if v != background}
            if len(features) != 1:
                continue
            value = next(iter(features))
            for a, b in tile_groups:
                i = a + offset
                if axis == 0:
                    if out[i][j] == background:
                        out[i][j] = value
                elif out[j][i] == background:
                    out[j][i] = value
    return out
